#include "uart_workbench.h"
#include "uart_tool_form.h"
#include "uart_files.h"
#include <cmath>
#include <sstream>
bool UartWorkbench::start_rtu(size_t i,RtuConfig config,std::wstring& error){std::string detail;if(!validate_rtu(config,detail)){error=uart_wide(detail);return false;}Request clock;clock.action=Request::CheckClock;if(!request(clock)){error=L"RTU charts require PC receipt time. Unload offline work and clear the text Time field/group first.";return false;}if(!acquire(i,ToolRun::Modbus,error))return false;if(!rtu_[i].start(config,runs_[i].generation,GetTickCount64(),detail)){runs_[i].kind=ToolRun::None;error=uart_wide(detail);return false;}rtu_config_[i]=std::move(config);if(i==0){Request r;r.action=Request::DiscardText;request(r);}return true;}
void UartWorkbench::poll_rtu(size_t i,uint64_t now){auto& run=runs_[i];auto& poller=rtu_[i];const auto batch=(i==0?*primary_:secondary_.traffic).after(run.sequence,32);if(batch.revision!=run.revision||(!batch.records.empty()&&batch.records.front().sequence>run.sequence+1))poller.stop("RTU stopped: raw RX history gap");for(const auto& record:batch.records){run.sequence=record.sequence;if(!record.tx)poller.receive(record.bytes,now,record.sample_seconds);}poller.tick(now);std::string bytes;if(!run.id&&poller.next(now,bytes)){std::wstring error;if(!submit_tool(i,std::move(bytes),error,true))poller.stop(message_utf8(error));}
    if(auto result=poller.take()){BinaryFrame frame;frame.bytes=std::move(result->bytes);frame.sample_seconds=result->seconds;if(rtu_config_[i].fields.empty()){for(size_t n=0;n<result->registers.size();++n)frame.values.push_back({"RTU.r"+std::to_string(rtu_config_[i].address+n),static_cast<double>(result->registers[n])});}else for(const auto& value:result->values)frame.values.push_back({"RTU."+value.first,value.second});decoded_bytes_+=frame.bytes.size();decoded_.push_back({i,std::move(frame)});while(decoded_.size()>256||decoded_bytes_>2*1024*1024){decoded_bytes_-=decoded_.front().frame.bytes.size();decoded_.pop_front();}}
    run.status=uart_wide(poller.status());if(!poller.active()){const auto status=run.status;stop_tool(i);run.status=status;groups_[i].save_error=status;}
}
void UartWorkbench::rtu_dialog(size_t i){const auto generation=i==0?primary_status_.generation:secondary_.generation();const auto config=rtu_config_[i];std::wstring schema;for(const auto& f:config.fields){if(!schema.empty())schema+=L"\r\n";schema+=uart_wide(f.name)+L","+std::to_wstring(f.reg)+L","+uart_wide(f.type)+L","+uart_wide(f.order)+L","+std::to_wstring(f.scale)+L","+std::to_wstring(f.add);}
    const auto convert=[i,this](const std::vector<std::wstring>& f,RtuConfig& out,std::wstring& error){double values[5]{};const unsigned low[]={1,0,1,100,100},high[]={247,65535,125,60000,60000};const size_t indexes[]={0,2,3,4,5};for(size_t n=0;n<5;++n)if(!uart_number(f[indexes[n]],low[n],high[n],values[n])||values[n]!=std::floor(values[n])){error=L"Invalid integer unit/address/count/interval/timeout.";return false;}out.unit=static_cast<unsigned>(values[0]);out.address=static_cast<unsigned>(values[1]);out.count=static_cast<unsigned>(values[2]);out.period_ms=static_cast<unsigned>(values[3]);out.timeout_ms=static_cast<unsigned>(values[4]);out.function=f[1]==L"03 Holding"?3:4;const auto& s=i==0?primary_status_.settings:secondary_.settings();const double bits=1+s.data_bits+(s.parity==NOPARITY?0:1)+(s.stop_bits==TWOSTOPBITS?2:s.stop_bits==ONE5STOPBITS?1.5:1);out.idle_ms=s.baud>19200?2:static_cast<unsigned>(std::ceil(3500*bits/std::max(1,s.baud)));std::string detail;if(!parse_rtu_fields(message_utf8(f[6]),out.fields,detail)||!validate_rtu(out,detail)){error=uart_wide(detail);return false;}return true;};
    UartToolForm form(i?L"Modbus RTU - Port B":L"Modbus RTU - Port A",L"Read-only FC03/04. Addresses/word offsets are zero-based decimal (40001 is address 0). Fields: name,word_offset,u16/i16/u32/i32/f32/f64[,ABCD/CDAB/BADC/DCBA[,scale[,add]]]. Empty fields chart every raw register. Word order reverses 16-bit words; BADC/DCBA also swap bytes. Stop on timeout/exception; no automatic retry. PC receipt gaps are not wire timing guarantees.",{{L"Unit",std::to_wstring(config.unit)},{L"Function",config.function==3?L"03 Holding":L"04 Input",{L"03 Holding",L"04 Input"}},{L"Start address",std::to_wstring(config.address)},{L"Register count",std::to_wstring(config.count)},{L"Poll interval (ms)",std::to_wstring(config.period_ms)},{L"Timeout (ms)",std::to_wstring(config.timeout_ms)},{L"Fields CSV",schema,{},5}},[convert](const auto& f){RtuConfig c;std::wstring error;if(!convert(f,c,error))return error;return L"Request HEX (preview only): "+tx_preview(rtu_request(c));},[convert](const auto& f,std::wstring& error){RtuConfig c;return convert(f,c,error);},this);
    if(form.DoModal()!=IDOK||shutdown_)return;if(generation!=(i==0?primary_status_.generation:secondary_.generation())){warn(L"Connection changed while choosing RTU options; review and start again.");return;}RtuConfig selected;std::wstring error;if(!convert(form.values(),selected,error)||!start_rtu(i,std::move(selected),error))warn(error);
}
void UartWorkbench::terminal_dialog(size_t i){
    auto& g=groups_[i];UartToolForm form(i?L"Terminal - Port B":L"Terminal - Port A",L"Receive-only, monochrome ASCII VT100-style screen: cursor/erase, scrolling region, tabs, insert/delete and DEC line drawing. SGR colors/query replies/keypad negotiation/UTF-8 wide cells are not emulated. Raw ASCII/HEX and recording remain unchanged. Apply rebuilds this screen from retained RX; it never transmits.",{{L"Columns (40..240)",std::to_wstring(g.terminal.columns())},{L"Rows (12..80)",std::to_wstring(g.terminal.rows())}},{},[](const auto& f,std::wstring& error){double a=0,b=0;if(!uart_number(f[0],40,240,a)||a!=std::floor(a)||!uart_number(f[1],12,80,b)||b!=std::floor(b)){error=L"Columns 40..240 and rows 12..80, whole numbers.";return false;}return true;},this);
    if(form.DoModal()!=IDOK||shutdown_)return;const auto values=form.values();double columns=0,rows=0;uart_number(values[0],40,240,columns);uart_number(values[1],12,80,rows);g.terminal.resize(static_cast<unsigned>(columns),static_cast<unsigned>(rows));g.terminal_generation=UINT64_MAX;for(const auto& record:(i==0?*primary_:secondary_.traffic).snapshot().records)if(!record.tx&&record.sequence<=g.sequence){if(g.terminal_generation!=record.generation){g.terminal.reset();g.terminal_generation=record.generation;}g.terminal.feed(record.bytes);}g.mode=3;::SendMessageW(g.view,CB_SETCURSEL,3,0);g.dirty=true;update_view(i);
}
